examples.command:
robocopy C:\{{DIR}} D:\{{DIR}} /E /COPYALL
rmdir /s /q C:\{{DIR}}
mklink /J C:\{{DIR}} D:\{{DIR}}

pwdadm -f ADMCHG {{USER}}
chuser account_locked=false {{USER}}
chsec -f /etc/security/lastlog -a unsuccessful_login_count=0 -s {{USER}}

syntax:
default:
        admin = false
        login = true
        rlogin = true
        loginretries = {{COUNT}}
        maxage = {{WEEKS}}
        minlen = {{LENGTH}}

examples.command:
$j = Start-Job -Name scan -ScriptBlock { Get-ChildItem C:\ -Recurse -Filter *.log -ErrorAction SilentlyContinue }
Get-Job
Receive-Job -Name scan -Wait -AutoRemoveJob

ioscan -fnNkC disk | grep NO_HW
strings /etc/lvmtab /etc/lvmtab_p | grep {{DISK}}
rmsf -a /dev/disk/{{DISK}}
ioscan -fnNkC disk

svccfg -s system/identity:node setprop config/nodename = {{HOSTNAME}}
svcadm refresh system/identity:node
svcadm restart system/identity:node

items.cmd:
add fs
set dir={{ZONE_DIR}}
set special={{GLOBAL_DIR}}
set type=lofs
end

examples.command:
route -p add -net {{NETWORK}}/{{PREFIX}} {{GATEWAY}}
route -p show
netstat -rn | grep {{NETWORK}}

netsh interface ip set address name="{{IFACE}}" static {{IP}} {{NETMASK}} {{GATEWAY}}
netsh interface ip set dns name="{{IFACE}}" static {{DNS1}}
netsh interface ip add dns name="{{IFACE}}" {{DNS2}} index=2

cat > upload.txt <<'EOF'
cd /upload
put {{FILE}}
-rm old_{{FILE}}
EOF
sftp -b upload.txt {{USER}}@{{HOST}}

export PATH=$PATH:/opt/freeware/bin
dnf repolist
dnf install {{PACKAGE}}

add-apt-repository -y ppa:{{PPA_USER}}/{{PPA_NAME}}
apt update
apt install {{PACKAGE}}

newfs -F vxfs -o largefiles -b 8192 /dev/{{VG}}/r{{LV}}
mkdir {{MOUNT_POINT}}
mount -F vxfs -o delaylog,largefiles /dev/{{VG}}/{{LV}} {{MOUNT_POINT}}
bdf {{MOUNT_POINT}}

mkfs.xfs {{DEVICE}}
mkdir -p {{MOUNT_POINT}}
echo "UUID=$(blkid -s UUID -o value {{DEVICE}}) {{MOUNT_POINT}} xfs defaults,nofail 0 0" >> /etc/fstab
systemctl daemon-reload
mount -a
df -hT {{MOUNT_POINT}}

lvcreate -L 10240 -n {{LV}} /dev/{{VG}}
newfs -F vxfs -o largefiles /dev/{{VG}}/r{{LV}}
mkdir {{MOUNT_POINT}}
mount -F vxfs -o delaylog /dev/{{VG}}/{{LV}} {{MOUNT_POINT}}
bdf {{MOUNT_POINT}}

ioscan -fnNC disk
diskinfo /dev/rdisk/{{DISK}}
strings /etc/lvmtab /etc/lvmtab_p | grep {{DISK}}
pvcreate /dev/rdisk/{{DISK}}

lvcreate -n {{LV}} -l 100%FREE {{VG}}
mkfs.xfs /dev/{{VG}}/{{LV}}
mkdir -p {{MOUNT_POINT}}
echo '/dev/mapper/{{VG}}-{{LV}} {{MOUNT_POINT}} xfs defaults 0 0' >> /etc/fstab
systemctl daemon-reload
mount -a

{{MOUNT_POINT}}:
        dev             = {{REMOTE_PATH}}
        vfs             = nfs
        nodename        = {{NFS_SERVER}}
        mount           = true
        options         = bg,hard,intr,vers=3

mount -F nfs {{HOST}}:{{EXPORT_PATH}} {{MOUNT_POINT}}
lofiadm -a {{ISO_FILE}}
mount -F hsfs -o ro /dev/lofi/1 {{MOUNT_POINT}}

aa-complain /etc/apparmor.d/{{PROFILE}}
# 확인 후 다시 enforce
aa-enforce /etc/apparmor.d/{{PROFILE}}

export http_proxy=http://{{HOST}}:{{PORT}}
export https_proxy=$http_proxy
export no_proxy=localhost,127.0.0.1,.{{DOMAIN}}

if (!(Test-Path $PROFILE)) { New-Item -ItemType File -Path $PROFILE -Force }
Add-Content $PROFILE 'function ll { Get-ChildItem -Force @args }'
. $PROFILE
